+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { useCallback, useEffect, useRef, useState } from "react";
+import { Room } from "matrix-js-sdk/src/models/room";
+import { RoomMember } from "matrix-js-sdk/src/models/room-member";
+import { MatrixEvent } from "matrix-js-sdk/src/models/event";
+import { logger } from "matrix-js-sdk/src/logger";
+
+import dis from "../dispatcher/dispatcher";
+import { Action } from "../dispatcher/actions";
+import { MatrixClientPeg } from "../MatrixClientPeg";
+import { ButtonEvent } from "../components/views/elements/AccessibleButton";
+import { PillType } from "../components/views/elements/Pill";
+import { getPrimaryPermalinkEntity, parsePermalink } from "../utils/permalinks/Permalinks";
+
+interface Args {
+    /** Room in which the permalink should be displayed. */
+    room?: Room;
+    /** When set forces the permalink type. */
+    type?: PillType;
+    /** Permalink URL. */
+    url?: string;
+    /** Whether the permalink is in a message. */
+    inMessage?: boolean;
+}
+
+interface HookResult {
+    /**
+     * Room member of a user mention permalink.
+     * null for other links, if the profile was not found or not yet loaded.
+     */
+    member: RoomMember | null;
+    /**
+     * Displayable text of the permalink resource. Can for instance be a user or room name.
+     * null here means that there is nothing to display. Most likely if the URL was not a permalink.
+     */
+    text: string | null;
+    /**
+     * Should be used for click actions on the permalink.
+     * In case of a user permalink, a view profile action is dispatched.
+     */
+    onClick: (e: ButtonEvent) => void;
+    /**
+     * This can be for instance a user or room Id.
+     * null here means that the resource cannot be detected. Most likely if the URL was not a permalink.
+     */
+    resourceId: string | null;
+    /**
+     * Target room of the permalink:
+     * For an @room mention, this is the room where the permalink should be displayed.
+     * For a room permalink, it is the room from the permalink.
+     * null for other links or if the room cannot be found.
+     */
+    targetRoom: Room | null;
+    /**
+     * Type of the pill plus "space" for spaces.
+     * null here means unknown/error.
+     */
+    type: PillType | null;
+}
+
+/**
+ * Tries to determine the pill type.
+ *
+ * If forcedType is set, this will be returned.
+ * If the parsed permalink contains an entity type, this will be returned.
+ *
+ * @param resourceId Permalink resource Id
+ * @param forcedType Forced pill type or undefined
+ * @returns Pill type or null if unable to determine
+ */
+const determineType = (resourceId: string | null, forcedType?: PillType): PillType | null => {
+    if (forcedType) return forcedType;
+
+    const prefix = resourceId?.[0] || "";
+    return (
+        {
+            "@": PillType.UserMention,
+            "#": PillType.RoomMention,
+            "!": PillType.RoomMention,
+        }[prefix] || null
+    );
+};
+
+/**
+ * Can be used to retrieve all information to display a permalink.
+ */
+export const usePermalink = ({ room: permalinkRoom, type: forcedType, url, inMessage }: Args): HookResult => {
+    const [member, setMember] = useState<RoomMember | null>(null);
+    // room of the entity this pill points to
+    const [targetRoom, setTargetRoom] = useState<Room | null>(permalinkRoom ?? null);
+    const unmounted = useRef(false);
+
+    useEffect(() => {
+        unmounted.current = false;
+        return () => {
+            unmounted.current = true;
+        };
+    }, []);
+
+    let resourceId: string | null = null;
+
+    if (url) {
+        if (inMessage) {
+            const parseResult = parsePermalink(url);
+            resourceId = parseResult?.primaryEntityId ?? null;
+        } else {
+            resourceId = getPrimaryPermalinkEntity(url) ?? null;
+        }
+    }
+
+    const type = determineType(resourceId, forcedType);
+
+    const doProfileLookup = useCallback((userId: string): void => {
+        MatrixClientPeg.get()
+            .getProfileInfo(userId)
+            .then((resp) => {
+                if (unmounted.current) return;
+
+                const newMember = new RoomMember(null, userId);
+                newMember.name = resp.displayname;
+                newMember.rawDisplayName = resp.displayname;
+                newMember.events.member = {
+                    getContent: () => {
+                        return { avatar_url: resp.avatar_url };
+                    },
+                    getDirectionalContent: function (): object {
+                        return this.getContent();
+                    },
+                } as MatrixEvent;
+                setMember(newMember);
+            })
+            .catch((err) => {
+                logger.error("Could not retrieve profile data for " + userId + ":", err);
+            });
+    }, []);
+
+    useEffect(() => {
+        switch (type) {
+            case PillType.AtRoomMention:
+                setTargetRoom(permalinkRoom ?? null);
+                break;
+            case PillType.UserMention:
+                if (resourceId) {
+                    const localMember = permalinkRoom?.getMember(resourceId) ?? null;
+
+                    if (localMember) {
+                        setMember(localMember);
+                    } else {
+                        setMember(new RoomMember(null, resourceId));
+                        doProfileLookup(resourceId);
+                    }
+                }
+                break;
+            case PillType.RoomMention:
+                if (resourceId) {
+                    const newRoom =
+                        resourceId[0] === "#"
+                            ? MatrixClientPeg.get()
+                                  .getRooms()
+                                  .find((r) => {
+                                      return (
+                                          r.getCanonicalAlias() === resourceId ||
+                                          r.getAltAliases().includes(resourceId)
+                                      );
+                                  }) ?? null
+                            : MatrixClientPeg.get().getRoom(resourceId);
+                    setTargetRoom(newRoom);
+                }
+                break;
+        }
+        // eslint-disable-next-line react-hooks/exhaustive-deps
+    }, [permalinkRoom, resourceId, type]);
+
+    let onClick: (e: ButtonEvent) => void = () => {};
+    let text = resourceId;
+
+    if (type === PillType.AtRoomMention && permalinkRoom) {
+        text = "@room";
+    } else if (type === PillType.UserMention && member) {
+        text = member.rawDisplayName || resourceId;
+        onClick = (e: ButtonEvent): void => {
+            e.preventDefault();
+            dis.dispatch({
+                action: Action.ViewUser,
+                member: member,
+            });
+        };
+    } else if (type === PillType.RoomMention) {
+        if (targetRoom) {
+            text = targetRoom.name || resourceId;
+        }
+    }
+
+    return {
+        member,
+        onClick,
+        resourceId,
+        targetRoom,
+        text,
+        type,
+    };
+};
