+
+SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+Please see LICENSE files in the repository root for full details.
+*/
+
+import { type ReactNode } from "react";
+import { createRoot, type Root } from "react-dom/client";
+
+/**
+ * Utility class to render & unmount additional React roots,
+ * e.g. for pills, tooltips and other components rendered atop user-generated events.
+ *
+ * It replaces the legacy `ReactDOM.render` / `ReactDOM.unmountComponentAtNode` usage with
+ * the modern `createRoot` API from `react-dom/client`, providing a consistent and reusable
+ * abstraction which ensures proper lifecycle management (mounting & unmounting).
+ */
+export class ReactRootManager {
+    private roots: Root[] = [];
+    private rootElements: Element[] = [];
+
+    /**
+     * The DOM elements into which React roots have been rendered by this manager.
+     */
+    public get elements(): Element[] {
+        return this.rootElements;
+    }
+
+    /**
+     * Render a React subtree into the given root element using `createRoot`,
+     * keeping track of it so it can be unmounted later.
+     *
+     * @param children the React node to render
+     * @param rootElement the DOM element to render into
+     */
+    public render(children: ReactNode, rootElement: Element): void {
+        const root = createRoot(rootElement);
+        this.roots.push(root);
+        this.rootElements.push(rootElement);
+        root.render(children);
+    }
+
+    /**
+     * Unmount all the React roots managed by this instance.
+     *
+     * It is critical to call this to avoid leaking React subtrees (and the entire
+     * DOM trees they may reference) once they are no longer needed.
+     */
+    public unmount(): void {
+        while (this.roots.length) {
+            const root = this.roots.pop()!;
+            this.rootElements.pop();
+            root.unmount();
+        }
+    }
+}
