+distributed under the License is distributed on an "AS IS" BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { logger } from "matrix-js-sdk/src/logger";
+import { IMatrixProfile, MatrixClient, MatrixEvent, RoomMember, RoomMemberEvent } from "matrix-js-sdk/src/matrix";
+
+/**
+ * Stores and caches user profiles (display name and avatar) to avoid redundant
+ * profile lookups against the homeserver API.
+ *
+ * A profile can either be a regular profile (see {@link fetchProfile}) that can
+ * be looked up for any user, or an "only known" profile (see
+ * {@link fetchOnlyKnownProfile}) that is only looked up if there is at least one
+ * room shared with the corresponding user.
+ *
+ * The cache is invalidated for a user if a membership update with different
+ * profile values is received for that user.
+ */
+export class UserProfilesStore {
+    /**
+     * Cache of user Id → profile.
+     * A null value means: the user does not exist / the profile could not be fetched.
+     * An undefined value (missing key) means: the profile has not been fetched yet.
+     */
+    private profiles = new Map<string, IMatrixProfile | null>();
+
+    /**
+     * Cache of user Id → profile of known users.
+     * A known user is a user that shares at least one room with the current user.
+     * A null value means: the user does not exist / the profile could not be fetched.
+     * An undefined value (missing key) means: the profile has not been fetched yet.
+     */
+    private knownProfiles = new Map<string, IMatrixProfile | null>();
+
+    public constructor(private client: MatrixClient) {
+        client.on(RoomMemberEvent.Membership, this.onRoomMembershipEvent);
+    }
+
+    /**
+     * Synchronously get a profile from the store cache.
+     *
+     * @param userId - User Id of the profile to get
+     * @returns The profile, if cached by the store.
+     *          Null if the profile does not exist.
+     *          Undefined if the profile is not cached by the store.
+     *          In this case a profile can be fetched from the API via {@link fetchProfile}.
+     */
+    public getProfile(userId: string): IMatrixProfile | undefined | null {
+        return this.profiles.get(userId);
+    }
+
+    /**
+     * Fetch a profile from the API and stores it in the cache.
+     *
+     * @param userId - User Id of the profile to fetch
+     * @returns The profile information or null if the profile does not exist or an error occurred
+     */
+    public async fetchProfile(userId: string): Promise<IMatrixProfile | null> {
+        const profile = await this.fetchProfileFromApi(userId);
+        this.profiles.set(userId, profile);
+        return profile;
+    }
+
+    /**
+     * Synchronously get a profile from the known users store cache.
+     * Known user means that at least one shared room with the user exists.
+     *
+     * @param userId - User Id of the profile to get
+     * @returns The profile, if cached by the store.
+     *          Null if the profile does not exist.
+     *          Undefined if the profile is not cached by the store.
+     *          In this case a profile can be fetched from the API via {@link fetchOnlyKnownProfile}.
+     */
+    public getOnlyKnownProfile(userId: string): IMatrixProfile | undefined | null {
+        return this.knownProfiles.get(userId);
+    }
+
+    /**
+     * Fetch a profile from a known user (see {@link getOnlyKnownProfile}) from the API
+     * and stores it in the cache.
+     *
+     * @param userId - User Id of the profile to fetch
+     * @returns The profile information.
+     *          Null if the profile does not exist or an error occurred while fetching it.
+     *          Undefined if the user is not known (no shared room). In this case the profile won't be cached.
+     */
+    public async fetchOnlyKnownProfile(userId: string): Promise<IMatrixProfile | undefined | null> {
+        // Do not look up unknown users. Their profile won't be populated in the cache.
+        if (!this.isUserIdKnown(userId)) return undefined;
+
+        const profile = await this.fetchProfileFromApi(userId);
+        this.knownProfiles.set(userId, profile);
+        return profile;
+    }
+
+    /**
+     * Looks up a user profile via API.
+     *
+     * @param userId - User Id for which the profile should be looked up
+     * @returns The profile information or null on errors
+     */
+    private async fetchProfileFromApi(userId: string): Promise<IMatrixProfile | null> {
+        try {
+            return (await this.client.getProfileInfo(userId)) ?? null;
+        } catch (e) {
+            logger.warn(`Error retrieving profile for userId ${userId}`, e);
+        }
+
+        return null;
+    }
+
+    /**
+     * Whether at least one shared room with the userId exists.
+     *
+     * @param userId
+     * @returns true: at least one room shared with user identified by its Id, else false.
+     */
+    private isUserIdKnown(userId: string): boolean {
+        return this.client.getRooms().some((room) => {
+            return !!room.getMember(userId);
+        });
+    }
+
+    /**
+     * Simple cache invalidation if a room membership changes for a cached profile
+     * with different values.
+     *
+     * @param event - Event that might trigger the invalidation
+     * @param member - Corresponding room member
+     */
+    private onRoomMembershipEvent = (event: MatrixEvent, member: RoomMember): void => {
+        this.maybeInvalidateCache(this.profiles, member);
+        this.maybeInvalidateCache(this.knownProfiles, member);
+    };
+
+    /**
+     * Invalidates the cache entry for the room member if it is cached with different values.
+     *
+     * @param cache - Cache to inspect and invalidate
+     * @param member - Room member for which the cache should be invalidated
+     */
+    private maybeInvalidateCache(cache: Map<string, IMatrixProfile | null>, member: RoomMember): void {
+        if (!cache.has(member.userId)) return;
+
+        const cachedProfile = cache.get(member.userId);
+
+        if (
+            cachedProfile &&
+            (cachedProfile.displayname !== member.rawDisplayName ||
+                cachedProfile.avatar_url !== member.getMxcAvatarUrl())
+        ) {
+            // The profile changed → invalidate the cache.
+            cache.delete(member.userId);
+        }
+    }
+}

