@@ -0,0 +1,133 @@
+/*
+ * Copyright 2024 New Vector Ltd.
+ *
+ * SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+ * Please see LICENSE files in the repository root for full details.
+ */
+
+import React, { HTMLProps, JSX, useState } from "react";
+import { IContent, M_POLL_START, MatrixEvent, MatrixEventEvent, MsgType } from "matrix-js-sdk/src/matrix";
+import classNames from "classnames";
+
+import { _t } from "../../../languageHandler";
+import { MessagePreviewStore } from "../../../stores/room-list/MessagePreviewStore";
+import { useAsyncMemo } from "../../../hooks/useAsyncMemo";
+import { useMatrixClientContext } from "../../../contexts/MatrixClientContext";
+import { useTypedEventEmitter } from "../../../hooks/useEventEmitter";
+
+interface EventPreviewProps extends HTMLProps<HTMLSpanElement> {
+    /**
+     * The event to display the preview for
+     */
+    mxEvent: MatrixEvent;
+}
+
+/**
+ * A component that displays a preview for the given event.
+ * Wraps both an optional localized type prefix (e.g. "Image", "Poll") and the
+ * generated message preview. The preview is regenerated on edits & decryption.
+ */
+export function EventPreview({ mxEvent, className, ...props }: EventPreviewProps): JSX.Element | null {
+    const preview = useEventPreview(mxEvent);
+    if (!preview) return null;
+
+    const { text, prefix } = preview;
+
+    // No prefix, just render the preview and set the title attribute for the tooltip
+    if (!prefix)
+        return (
+            <span className={classNames("mx_EventPreview", className)} title={text} {...props}>
+                {text}
+            </span>
+        );
+
+    return (
+        <span className={classNames("mx_EventPreview", className)} {...props}>
+            {_t(
+                "event_preview|preview",
+                {
+                    prefix,
+                    preview: text,
+                },
+                {
+                    bold: (sub) => <span className="mx_EventPreview_prefix">{sub}</span>,
+                },
+            )}
+        </span>
+    );
+}
+
+/**
+ * The preview of an event, containing the generated message preview and an optional localized type prefix.
+ */
+interface Preview {
+    /**
+     * The text of the preview.
+     */
+    text: string;
+    /**
+     * The localized type prefix of the preview, if any (e.g. "Image", "Poll").
+     */
+    prefix: string | null;
+}
+
+/**
+ * Hook to generate a preview for the event.
+ * Regenerates the preview upon edits & decryption of the event.
+ * @param mxEvent - The event to generate the preview for
+ * @returns The preview of the event or null if there is no preview
+ */
+export function useEventPreview(mxEvent: MatrixEvent | null): Preview | null {
+    const cli = useMatrixClientContext();
+    // track the content as a means to regenerate the preview upon edits & decryption
+    const [content, setContent] = useState<IContent | undefined>(mxEvent?.getContent());
+    useTypedEventEmitter(mxEvent ?? undefined, MatrixEventEvent.Replaced, () => {
+        setContent(mxEvent!.getContent());
+    });
+    const awaitDecryption = mxEvent?.shouldAttemptDecryption() || mxEvent?.isBeingDecrypted();
+    useTypedEventEmitter(awaitDecryption ? mxEvent : undefined, MatrixEventEvent.Decrypted, () => {
+        setContent(mxEvent!.getContent());
+    });
+
+    return useAsyncMemo(
+        async () => {
+            if (!mxEvent || mxEvent.isRedacted() || mxEvent.isDecryptionFailure()) return null;
+            await cli.decryptEventIfNeeded(mxEvent);
+            const text = MessagePreviewStore.instance.generatePreviewForEvent(mxEvent);
+            if (!text) return null;
+            return {
+                text,
+                prefix: getPreviewPrefix(mxEvent.getType(), mxEvent.getContent().msgtype as MsgType),
+            };
+        },
+        [mxEvent, content],
+        null,
+    );
+}
+
+/**
+ * Get the localized type prefix for the preview based on the event type and the message type.
+ * @param type - The event type
+ * @param msgType - The message type
+ * @returns The localized prefix or null if there is no prefix for the given type
+ */
+function getPreviewPrefix(type: string, msgType: MsgType): string | null {
+    switch (type) {
+        case M_POLL_START.name:
+            return _t("event_preview|prefix|poll");
+        default:
+    }
+
+    switch (msgType) {
+        case MsgType.Audio:
+            return _t("event_preview|prefix|audio");
+        case MsgType.Image:
+            return _t("event_preview|prefix|image");
+        case MsgType.Video:
+            return _t("event_preview|prefix|video");
+        case MsgType.File:
+            return _t("event_preview|prefix|file");
+        default:
+            return null;
+    }
+}
